  1→<script lang="ts">
  2→	// AC: @web-dashboard ac-5, ac-6, ac-7, ac-8
  3→	// Custom sheet implementation for task details
  4→	import type { TaskDetail as TaskDetailType } from '@kynetic-ai/shared';
  5→	import { base } from '$app/paths';
  6→	import { Button } from '$lib/components/ui/button';
  7→	import { Badge } from '$lib/components/ui/badge';
  8→	import { Textarea } from '$lib/components/ui/textarea';
  9→	import { Separator } from '$lib/components/ui/separator';
 10→	import { startTask, addTaskNote } from '$lib/api';
 11→	import XIcon from '@lucide/svelte/icons/x';
 12→
 13→	// Props for controlling the panel - use $bindable for reactivity
 14→	let {
 15→		open = $bindable(false),
 16→		task = $bindable<TaskDetailType | null>(null),
 17→		onclose = undefined as (() => void) | undefined,
 18→		onupdate = undefined as (() => void) | undefined
 19→	} = $props();
 20→
 21→	// Debug: log when props change
 22→	$effect(() => {
 23→		console.log('[TaskDetailPanel] open changed to:', open, 'task:', task?.title);
 24→	});
 25→
 26→	let noteContent = $state('');
 27→	let isSubmitting = $state(false);
 28→	let error = $state('');
 29→
 30→	function close() {
 31→		onclose?.();
 32→	}
 33→
 34→	// Handle clicking outside the panel
 35→	function handleOverlayClick(e: MouseEvent) {
 36→		if (e.target === e.currentTarget) {
 37→			close();
 38→		}
 39→	}
 40→
 41→	// Handle escape key
 42→	function handleKeydown(e: KeyboardEvent) {
 43→		if (e.key === 'Escape' && open) {
 44→			close();
 45→		}
 46→	}
 47→
 48→	async function handleStartTask() {
 49→		if (!task) return;
 50→
 51→		isSubmitting = true;
 52→		error = '';
 53→
 54→		try {
 55→			await startTask(task._ulid);
 56→			onupdate?.();
 57→			close();
 58→		} catch (err) {
 59→			error = err instanceof Error ? err.message : 'Failed to start task';
 60→		} finally {
 61→			isSubmitting = false;
 62→		}
 63→	}
 64→
 65→	async function handleAddNote() {
 66→		if (!task || !noteContent.trim()) return;
 67→
 68→		isSubmitting = true;
 69→		error = '';
 70→
 71→		try {
 72→			await addTaskNote(task._ulid, noteContent);
 73→			noteContent = '';
 74→			onupdate?.();
 75→		} catch (err) {
 76→			error = err instanceof Error ? err.message : 'Failed to add note';
 77→		} finally {
 78→			isSubmitting = false;
 79→		}
 80→	}
 81→
 82→	function formatDate(dateStr: string): string {
 83→		const date = new Date(dateStr);
 84→		return new Intl.DateTimeFormat('en-US', {
 85→			year: 'numeric',
 86→			month: 'short',
 87→			day: 'numeric',
 88→			hour: '2-digit',
 89→			minute: '2-digit'
 90→		}).format(date);
 91→	}
 92→
 93→	function getStatusColor(status: string): string {
 94→		const colors: Record<string, string> = {
 95→			pending: 'bg-gray-500',
 96→			in_progress: 'bg-blue-500',
 97→			pending_review: 'bg-yellow-500',
 98→			blocked: 'bg-red-500',
 99→			completed: 'bg-green-500',
100→			cancelled: 'bg-gray-400'
101→		};
102→		return colors[status] || 'bg-gray-500';
103→	}
104→</script>
105→
106→<svelte:window onkeydown={handleKeydown} />
107→
108→{#if open && task}
109→	<!-- Overlay -->
110→	<div
111→		class="fixed inset-0 z-50 bg-black/50"
112→		onclick={handleOverlayClick}
113→		onkeydown={(e) => e.key === 'Enter' && close()}
114→		role="button"
115→		tabindex="-1"
116→		aria-label="Close panel"
117→	>
118→		<!-- Panel -->
119→		<div
120→			class="fixed inset-y-0 right-0 z-50 w-3/4 max-w-lg bg-background shadow-lg border-l overflow-y-auto animate-in slide-in-from-right duration-300"
121→			data-testid="task-detail-panel"
122→			role="dialog"
123→			aria-modal="true"
124→			onclick={(e) => e.stopPropagation()}
125→			onkeydown={(e) => e.stopPropagation()}
126→		>
127→			<!-- Header -->
128→			<div class="flex items-center justify-between p-6 border-b">
129→				<h2 class="text-lg font-semibold" data-testid="task-description">{task.title}</h2>
130→				<button
131→					onclick={close}
132→					class="rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
133→				>
134→					<XIcon class="size-4" />
135→					<span class="sr-only">Close</span>
136→				</button>
137→			</div>
138→
139→			<!-- Content -->
140→			<div class="flex flex-col gap-4 p-6">
141→				<!-- Status and Priority -->
142→				<div class="flex gap-2 items-center">
143→					<Badge class={getStatusColor(task.status)}>{task.status}</Badge>
144→					<Badge variant="outline">Priority: {task.priority}</Badge>
145→					{#if task.type !== 'task'}
146→						<Badge variant="outline">{task.type}</Badge>
147→					{/if}
148→				</div>
149→
150→				<!-- Spec Reference -->
151→				<!-- AC: @web-dashboard ac-6 -->
152→				{#if task.spec_ref}
153→					<div data-testid="task-spec-ref-link">
154→						<p class="text-sm font-medium mb-1">Spec Reference:</p>
155→						<a
156→							href="{base}/items?ref={encodeURIComponent(task.spec_ref)}"
157→							class="text-sm text-primary hover:underline"
158→						>
159→							{task.spec_ref}
160→						</a>
161→					</div>
162→				{/if}
163→
164→				<!-- Tags -->
165→				{#if task.tags.length > 0}
166→					<div>
167→						<p class="text-sm font-medium mb-1">Tags:</p>
168→						<div class="flex flex-wrap gap-1">
169→							{#each task.tags as tag}
170→								<Badge variant="secondary">{tag}</Badge>
171→							{/each}
172→						</div>
173→					</div>
174→				{/if}
175→
176→				<!-- Dependencies -->
177→				<div data-testid="task-dependencies">
178→					{#if task.depends_on.length > 0}
179→						<p class="text-sm font-medium mb-1">Dependencies:</p>
180→						<ul class="text-sm space-y-1">
181→							{#each task.depends_on as dep}
182→								<li>
183→									<a href="{base}/tasks?ref={encodeURIComponent(dep)}" class="text-primary hover:underline">
184→										{dep}
185→									</a>
186→								</li>
187→							{/each}
188→						</ul>
189→					{:else}
190→						<p class="text-sm text-muted-foreground">No dependencies</p>
191→					{/if}
192→				</div>
193→
194→				<!-- Blocked By -->
195→				{#if task.blocked_by.length > 0}
196→					<div>
197→						<p class="text-sm font-medium mb-1 text-destructive">Blocked By:</p>
198→						<ul class="text-sm space-y-1">
199→							{#each task.blocked_by as blocker}
200→								<li class="text-muted-foreground">{blocker}</li>
201→							{/each}
202→						</ul>
203→					</div>
204→				{/if}
205→
206→				<Separator />
207→
208→				<!-- Actions -->
209→				<!-- AC: @web-dashboard ac-7 -->
210→				{#if task.status === 'pending'}
211→					<div>
212→						<Button data-testid="start-task-button" onclick={handleStartTask} disabled={isSubmitting} class="w-full">
213→							{isSubmitting ? 'Starting...' : 'Start Task'}
214→						</Button>
215→					</div>
216→				{/if}
217→
218→				{#if error}
219→					<p class="text-sm text-destructive">{error}</p>
220→				{/if}
221→
222→				<Separator />
223→
224→				<!-- Todos -->
225→				<div data-testid="task-todos">
226→					{#if task.todos && task.todos.length > 0}
227→						<p class="text-sm font-medium mb-2">Todos:</p>
228→						<ul class="space-y-2">
229→							{#each task.todos as todo}
230→								<li class="flex items-start gap-2 text-sm">
231→									<span class="mt-0.5">
232→										{#if todo.status === 'completed'}
233→											✅
234→										{:else if todo.status === 'in_progress'}
235→											⏳
236→										{:else}
237→											⏸️
238→										{/if}
239→									</span>
240→									<span class:line-through={todo.status === 'completed'}>
241→										{todo.content}
242→									</span>
243→								</li>
244→							{/each}
245→						</ul>
246→					{:else}
247→						<p class="text-sm text-muted-foreground">No todos</p>
248→					{/if}
249→				</div>
250→
251→				<Separator />
252→
253→				<!-- Notes -->
254→				<!-- AC: @web-dashboard ac-5 -->
255→				<div data-testid="task-notes">
256→					<p class="text-sm font-medium mb-2">Notes ({task.notes.length}):</p>
257→
258→					<!-- Add Note Form -->
259→					<!-- AC: @web-dashboard ac-8 -->
260→					<div class="mb-4 space-y-2" data-testid="add-note-form">
261→						<Textarea
262→							placeholder="Add a note..."
263→							bind:value={noteContent}
264→							disabled={isSubmitting}
265→							rows={3}
266→							data-testid="note-textarea"
267→						/>
268→						<Button
269→							onclick={handleAddNote}
270→							disabled={isSubmitting || !noteContent.trim()}
271→							size="sm"
272→							data-testid="add-note-button"
273→						>
274→							{isSubmitting ? 'Adding...' : 'Add Note'}
275→						</Button>
276→					</div>
277→
278→					<!-- Notes List -->
279→					<div class="space-y-4" data-testid="task-notes-list">
280→						{#each task.notes as note}
281→							<div class="border rounded-lg p-3" data-testid="note-item">
